    "party_size": {
      "exclusiveMinimum": 0,
      "title": "Party Size",
      "type": "integer"
    },
    "time": {
      "anyOf": [
        {
          "pattern": "^([01][0-9]|2[0-3]):[0-5][0-9]$",
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "default": null,
      "title": "Time"
    }
  },
  "required": [
    "date",
    "party_size"
  ],
  "title": "BATP AVAILABILITY params",
  "type": "object"
}

